<?php
require 'db.php';require_role(['Restaurant','Admin']);$me=user();$where=$me['role']==='Admin'?'1=1':'owner_user_id=?';$s=$conn->prepare("SELECT * FROM restaurants WHERE $where ORDER BY name LIMIT 1");if($me['role']!=='Admin')$s->bind_param('i',$me['id']);$s->execute();$restaurant=$s->get_result()->fetch_assoc();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add_item'])){check_csrf();if(!$restaurant)$error='Ask an administrator to create your restaurant profile first.';else{$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=max(0,(float)($_POST['price']??0));$stock=max(0,(int)($_POST['stock']??0));$cat=(int)($_POST['category_id']??0);$s=$conn->prepare('INSERT INTO menu_items(restaurant_id,category_id,name,description,price,stock) VALUES(?,?,?,?,?,?)');$s->bind_param('iissdi',$restaurant['id'],$cat,$name,$desc,$price,$stock);if($s->execute())flash('Menu item added.');else $error='Could not add the menu item.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['stock_update'])){check_csrf();$id=(int)$_POST['item_id'];$stock=max(0,(int)$_POST['stock']);$s=$conn->prepare('UPDATE menu_items m JOIN restaurants r ON r.id=m.restaurant_id SET m.stock=?,m.is_available=? WHERE m.id=? AND (r.owner_user_id=? OR ?=1)');$available=$stock>0?1:0;$admin=$me['role']==='Admin'?1:0;$s->bind_param('iiiii',$stock,$available,$id,$me['id'],$admin);$s->execute();flash('Stock updated.');}
$cats=$conn->query('SELECT * FROM categories ORDER BY name');$items=null;if($restaurant){$s=$conn->prepare('SELECT m.*,c.name category FROM menu_items m LEFT JOIN categories c ON c.id=m.category_id WHERE m.restaurant_id=?');$s->bind_param('i',$restaurant['id']);$s->execute();$items=$s->get_result();}
page_start('Restaurant dashboard');?><section class="hero"><span class="pill">MERCHANT TOOLS</span><h1><?=h($restaurant['name']??'Restaurant dashboard')?></h1><p>Manage your menu and stock. New customer orders appear in the orders page for status updates.</p><a class="btn" href="orders.php">View orders</a></section><?php if($error):?><p class="pill"><?=h($error)?></p><?php endif;?><?php if($restaurant):?><div class="grid"><section class="card"><h2>Add a menu item</h2><form method="post"><?php csrf_field();?><label>Name</label><input class="field" name="name" required><label>Description</label><textarea class="field" name="description"></textarea><label>Category</label><select class="field" name="category_id"><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endwhile;?></select><label>Price (VND)</label><input class="field" name="price" type="number" min="0" step="1000" required><label>Stock</label><input class="field" name="stock" type="number" min="0" value="10"><button name="add_item">Add item</button></form></section><section class="card"><h2>Menu & stock</h2><?php while($m=$items->fetch_assoc()):?><form method="post" style="border-bottom:1px solid #eee;padding:8px 0"><?php csrf_field();?><input type="hidden" name="item_id" value="<?=$m['id']?>"><strong><?=h($m['name'])?></strong> · <?=number_format($m['price'],0)?> ₫ <label>Stock <input name="stock" type="number" min="0" value="<?=$m['stock']?>" style="width:65px"></label><button name="stock_update">Save</button></form><?php endwhile;?></section></div><?php else:?><p>There is no restaurant profile linked to this account. An admin can link one by setting its owner_user_id.</p><?php endif;?><?php page_end();
